import numpy as np, sys
from collections import defaultdict

def load(path):
    lines = open(path).read().splitlines()
    n = int(lines[0]); els=[]; xyz=[]
    for l in lines[2:2+n]:
        p = l.split(); els.append(p[0]); xyz.append([float(p[1]),float(p[2]),float(p[3])])
    return els, np.array(xyz)

els, X = load(sys.argv[1])
radii = {'H':0.32,'C':0.77,'N':0.71,'O':0.66,'F':0.57,'P':1.07,'Co':1.26}
nb = defaultdict(list)
for i in range(len(els)):
    for j in range(i+1, len(els)):
        cutoff = 1.25*(radii[els[i]]+radii[els[j]]) + 0.15
        if np.linalg.norm(X[i]-X[j]) < cutoff:
            nb[i].append(j); nb[j].append(i)

# connectivity: BFS from atom 0
seen=set([0]); stack=[0]
while stack:
    i=stack.pop()
    for j in nb[i]:
        if j not in seen: seen.add(j); stack.append(j)
print(f"atoms: {len(els)}, connected component size: {len(seen)}")

# neighbor counts by element
from collections import Counter
cnt = Counter()
for i,e in enumerate(els):
    cnt[(e, len(nb[i]))] += 1
print("(element, #neighbors): count")
for k,v in sorted(cnt.items()):
    print(f"  {k}: {v}")

# key atoms detail
def show(i, name):
    ns = ", ".join(f"{els[j]}{j}({np.linalg.norm(X[i]-X[j]):.2f})" for j in sorted(nb[i]))
    print(f"{name} {els[i]}{i}: {len(nb[i])} neighbors -> {ns}")
show(0,'Co'); show(1,'P_amidite'); show(5,'PPh2'); show(6,'PPh2')
show(3,'C_carbonyl'); show(51,'N'); show(52,'N'); show(53,'O_linker')
